// fleetswipe — swipe the whole bisks.net fleet, Tinder-style. Everything
// here is client-side: card data is a static snapshot (data/fleet.json,
// regenerated by sync-fleet.mjs from sites/*/site.json), decisions and deck
// order live in localStorage so a reload picks up where you left off, and a
// "shared fleet" is just the kept names round-tripped through a query string
// — no server, no per-user record anywhere.

const LS_ORDER = "fleetswipe.order.v1";
const LS_DECISIONS = "fleetswipe.decisions.v1";

const els = {
  stack: document.getElementById("stack"),
  remainingCount: document.getElementById("remainingCount"),
  keptCount: document.getElementById("keptCount"),
  skipBtn: document.getElementById("skipBtn"),
  keepBtn: document.getElementById("keepBtn"),
  undoBtn: document.getElementById("undoBtn"),
  resetBtn: document.getElementById("resetBtn"),
  viewFleetBtn: document.getElementById("viewFleetBtn"),
  backToDeckBtn: document.getElementById("backToDeckBtn"),
  deckView: document.getElementById("deckView"),
  fleetView: document.getElementById("fleetView"),
  sharedView: document.getElementById("sharedView"),
  fleetList: document.getElementById("fleetList"),
  fleetSummary: document.getElementById("fleetSummary"),
  sharedList: document.getElementById("sharedList"),
  sharedTitle: document.getElementById("sharedTitle"),
  startOwnBtn: document.getElementById("startOwnBtn"),
  shareBtn: document.getElementById("shareBtn"),
  shareBluesky: document.getElementById("shareBluesky"),
  shareCanvas: document.getElementById("shareCanvas"),
};

let SITES = new Map(); // name -> site
let order = [];
let decisions = {}; // name -> "keep" | "skip"
let undoStack = [];
let topCardEl = null;
let busy = false;

function showView(view) {
  for (const v of [els.deckView, els.fleetView, els.sharedView]) v.classList.add("hidden");
  view.classList.remove("hidden");
}

function loadState() {
  try {
    decisions = JSON.parse(localStorage.getItem(LS_DECISIONS) || "{}");
  } catch {
    decisions = {};
  }
  try {
    order = JSON.parse(localStorage.getItem(LS_ORDER) || "null");
  } catch {
    order = null;
  }
  if (!Array.isArray(order) || order.length !== SITES.size) {
    order = shuffled([...SITES.keys()]);
    localStorage.setItem(LS_ORDER, JSON.stringify(order));
  }
}

function saveDecisions() {
  localStorage.setItem(LS_DECISIONS, JSON.stringify(decisions));
}

function shuffled(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function currentDeck() {
  return order.filter((name) => !(name in decisions));
}

function keptSites() {
  return order.filter((name) => decisions[name] === "keep").map((n) => SITES.get(n));
}

function updateCounters() {
  const remaining = currentDeck().length;
  els.remainingCount.textContent = remaining;
  els.keptCount.textContent = Object.values(decisions).filter((d) => d === "keep").length;
  els.undoBtn.disabled = undoStack.length === 0;
}

function typeEmoji(type) {
  return { toy: "🧸", game: "🎮", tool: "🛠️", joke: "🃏", explainer: "📖", art: "🎨" }[type] || "✨";
}

function renderCard(site, depth) {
  const card = document.createElement("div");
  card.className = "card";
  card.style.zIndex = String(10 - depth);
  card.style.transform = `translateY(${depth * 10}px) scale(${1 - depth * 0.04})`;
  card.innerHTML = `
    <span class="type">${typeEmoji(site.type)} ${site.type}</span>
    <h3>${escapeHtml(site.title)}</h3>
    <p class="by">by ${site.by ? "@" + escapeHtml(site.by) : "the daily slot"}</p>
    <p class="blurb">${escapeHtml(site.blurb)}</p>
    <span class="stamp keep">KEEP</span>
    <span class="stamp skip">SKIP</span>
  `;
  return card;
}

function escapeHtml(s) {
  const d = document.createElement("div");
  d.textContent = s;
  return d.innerHTML;
}

let dragState = null;

function renderStack() {
  els.stack.innerHTML = "";
  topCardEl = null;
  const deck = currentDeck();
  if (deck.length === 0) {
    const empty = document.createElement("div");
    empty.className = "empty";
    empty.textContent = "that's the whole fleet — nothing left to swipe.";
    els.stack.appendChild(empty);
    updateCounters();
    return;
  }
  const visible = deck.slice(0, 3);
  // append back-to-front so the top card ends up last in the DOM (z-index
  // still controls what's visually on top, but decide() needs a direct
  // reference to the top card rather than trusting DOM/query order)
  for (let i = visible.length - 1; i >= 0; i--) {
    const card = renderCard(SITES.get(visible[i]), i);
    els.stack.appendChild(card);
    if (i === 0) {
      wireDrag(card, visible[0]);
      topCardEl = card;
    }
  }
  updateCounters();
}

function wireDrag(card, name) {
  card.addEventListener("pointerdown", (e) => {
    card.setPointerCapture(e.pointerId);
    dragState = { startX: e.clientX, startY: e.clientY, dx: 0, dy: 0, name, card };
  });
  card.addEventListener("pointermove", (e) => {
    if (!dragState || dragState.card !== card) return;
    dragState.dx = e.clientX - dragState.startX;
    dragState.dy = e.clientY - dragState.startY;
    const rot = dragState.dx / 14;
    card.style.transform = `translate(${dragState.dx}px, ${dragState.dy}px) rotate(${rot}deg)`;
    const keepStamp = card.querySelector(".stamp.keep");
    const skipStamp = card.querySelector(".stamp.skip");
    keepStamp.style.opacity = String(Math.max(0, Math.min(1, dragState.dx / 100)));
    skipStamp.style.opacity = String(Math.max(0, Math.min(1, -dragState.dx / 100)));
  });
  const release = (e) => {
    if (!dragState || dragState.card !== card) return;
    const dx = dragState.dx;
    dragState = null;
    if (Math.abs(dx) > 100) {
      decide(name, dx > 0 ? "keep" : "skip");
    } else {
      card.style.transform = "";
      const keepStamp = card.querySelector(".stamp.keep");
      const skipStamp = card.querySelector(".stamp.skip");
      if (keepStamp) keepStamp.style.opacity = "0";
      if (skipStamp) skipStamp.style.opacity = "0";
    }
  };
  card.addEventListener("pointerup", release);
  card.addEventListener("pointercancel", release);
}

function decide(name, decision) {
  if (busy) return;
  busy = true;
  const card = topCardEl;
  undoStack.push(name);
  decisions[name] = decision;
  saveDecisions();
  if (card) {
    const flyX = decision === "keep" ? 600 : -600;
    card.style.transition = "transform 0.35s ease-out, opacity 0.35s ease-out";
    card.style.transform = `translate(${flyX}px, -40px) rotate(${flyX / 14}deg)`;
    card.style.opacity = "0";
    setTimeout(() => {
      renderStack();
      busy = false;
    }, 220);
  } else {
    renderStack();
    busy = false;
  }
}

function undo() {
  const name = undoStack.pop();
  if (!name) return;
  delete decisions[name];
  saveDecisions();
  renderStack();
}

function reset() {
  if (!confirm("start the whole deck over? this clears everything you've kept.")) return;
  decisions = {};
  undoStack = [];
  order = shuffled([...SITES.keys()]);
  localStorage.setItem(LS_ORDER, JSON.stringify(order));
  saveDecisions();
  renderStack();
}

function renderFleetView() {
  const kept = keptSites();
  const seen = order.filter((n) => n in decisions).length;
  els.fleetSummary.textContent = kept.length
    ? `kept ${kept.length} of ${seen} sites you've swiped so far (${SITES.size} total in the fleet).`
    : `nothing kept yet — swipe right on something first.`;
  els.fleetList.innerHTML = kept
    .map(
      (s) => `<li><a href="${s.url}" target="_blank" rel="noopener">${escapeHtml(s.title)}</a>
        <div class="fby">${typeEmoji(s.type)} ${s.type} · by ${s.by ? "@" + escapeHtml(s.by) : "the daily slot"}</div></li>`
    )
    .join("");
  const shareUrl = buildShareUrl(kept);
  const shareText = buildShareText(kept, shareUrl);
  els.shareBluesky.href = "https://bsky.app/intent/compose?text=" + encodeURIComponent(shareText);
  showView(els.fleetView);
}

function buildShareUrl(kept) {
  const names = kept.slice(0, 25).map((s) => s.name);
  const url = new URL("https://fleetswipe.bisks.net/");
  if (names.length) url.searchParams.set("fleet", names.join(","));
  return url.toString();
}

function buildShareText(kept, url) {
  if (!kept.length) return `swiping through the whole bisks.net fleet on fleetswipe → ${url}`;
  const names = kept.slice(0, 4).map((s) => s.title);
  let extra = kept.length > names.length ? ` +${kept.length - names.length} more` : "";
  let text = `swiped the bisks.net fleet and kept ${kept.length}: ${names.join(", ")}${extra} → ${url}`;
  // keep it inside bluesky's 300-grapheme budget with room to spare
  if (text.length > 280) {
    text = `swiped the bisks.net fleet and kept ${kept.length} sites → ${url}`;
  }
  return text;
}

function buildShareCard(kept) {
  const canvas = els.shareCanvas;
  const ctx = canvas.getContext("2d");
  const W = canvas.width, H = canvas.height;
  ctx.fillStyle = "#0f1115";
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = "#52d68a";
  ctx.font = "700 56px sans-serif";
  ctx.fillText("fleetswipe", 60, 100);
  ctx.fillStyle = "#9198a8";
  ctx.font = "28px sans-serif";
  ctx.fillText(`kept ${kept.length} of ${SITES.size} sites in the bisks.net fleet`, 60, 150);

  ctx.fillStyle = "#eef0f4";
  ctx.font = "34px sans-serif";
  let y = 230;
  for (const s of kept.slice(0, 8)) {
    ctx.fillText(`♥ ${s.title}`, 60, y);
    y += 50;
  }
  if (kept.length > 8) {
    ctx.fillStyle = "#9198a8";
    ctx.fillText(`+${kept.length - 8} more`, 60, y);
  }
  ctx.fillStyle = "#ff5f7e";
  ctx.font = "700 30px sans-serif";
  ctx.fillText("fleetswipe.bisks.net", 60, H - 50);
  return canvas;
}

function canShareFiles() {
  if (!navigator.share || !navigator.canShare) return false;
  const probe = new File([""], "probe.png", { type: "image/png" });
  return navigator.canShare({ files: [probe] });
}

async function doShare() {
  const kept = keptSites();
  const url = buildShareUrl(kept);
  const text = buildShareText(kept, url);
  const canvas = buildShareCard(kept);
  canvas.toBlob(async (blob) => {
    if (!blob) return;
    const file = new File([blob], "fleetswipe.png", { type: "image/png" });
    if (canShareFiles()) {
      try {
        await navigator.share({ files: [file], text, title: "my fleetswipe fleet" });
        return;
      } catch {
        // fall through to download
      }
    }
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = "fleetswipe.png";
    a.click();
  }, "image/png");
}

function renderSharedView(names) {
  const sites = names.map((n) => SITES.get(n)).filter(Boolean);
  els.sharedTitle.textContent = `someone's fleet (${sites.length} kept)`;
  els.sharedList.innerHTML = sites
    .map(
      (s) => `<li><a href="${s.url}" target="_blank" rel="noopener">${escapeHtml(s.title)}</a>
        <div class="fby">${typeEmoji(s.type)} ${s.type} · by ${s.by ? "@" + escapeHtml(s.by) : "the daily slot"}</div></li>`
    )
    .join("");
  showView(els.sharedView);
}

async function init() {
  const res = await fetch("/data/fleet.json");
  const data = await res.json();
  for (const s of data.sites) SITES.set(s.name, s);

  const params = new URLSearchParams(location.search);
  if (params.has("fleet")) {
    renderSharedView(params.get("fleet").split(",").filter(Boolean));
    els.startOwnBtn.addEventListener("click", () => {
      history.replaceState(null, "", "/");
      loadState();
      renderStack();
      showView(els.deckView);
    });
    return;
  }

  loadState();
  renderStack();

  els.skipBtn.addEventListener("click", () => {
    const deck = currentDeck();
    if (deck.length) decide(deck[0], "skip");
  });
  els.keepBtn.addEventListener("click", () => {
    const deck = currentDeck();
    if (deck.length) decide(deck[0], "keep");
  });
  els.undoBtn.addEventListener("click", undo);
  els.resetBtn.addEventListener("click", reset);
  els.viewFleetBtn.addEventListener("click", renderFleetView);
  els.backToDeckBtn.addEventListener("click", () => {
    renderStack();
    showView(els.deckView);
  });
  els.shareBtn.addEventListener("click", doShare);

  document.addEventListener("keydown", (e) => {
    if (els.deckView.classList.contains("hidden")) return;
    const deck = currentDeck();
    if (!deck.length) return;
    if (e.key === "ArrowLeft") decide(deck[0], "skip");
    if (e.key === "ArrowRight") decide(deck[0], "keep");
  });
}

init();
